const nativeId='11111111-1111-4111-8111-111111111111';
function nativeFixture(app,{messages=[],unreadCount=0,readSeq=0}={}){
 const conversation={id:nativeId,kind:'dm',name:'',title:'Friend',securityMode:'standard',participants:[{id:'account-a',username:'night_a',displayName:'Night A'},{id:'account-b',username:'friend_b',displayName:'Friend'}],lastSeq:messages.at(-1)?.seq||0,unreadCount,readSeq,readChangeSeq:0};
 app.server.replies.set('/api/messages/conversations',request=>request.method==='POST'?app.response({conversation},201):app.response({conversations:[conversation]}));
 app.server.replies.set('/api/messages/conversations/'+nativeId,app.response({conversation}));
 const payload={messages,changes:[],hasMore:false,cursor:messages.at(-1)?.seq||0,changeCursor:1,securityMode:'standard'};
 app.server.replies.set('/api/messages/conversations/'+nativeId+'/messages?'+(unreadCount?'after='+readSeq+'&limit=50':'limit=50'),app.response(payload));
 app.server.replies.set('/api/messages/conversations/'+nativeId+'/read',app.response({read:true}));
 return conversation;
}
const nativeMessage=(id='message-1',seq=1,text='Real standard message')=>({id,seq,conversation_id:nativeId,author_id:'account-b',author_name:'Friend',author_username:'friend_b',text,created_at:1700000000000,reactions:[]});
async function openConsentedNative(app,options={}){nativeFixture(app,options);await app.api.openNativeConversation(nativeId);await app.api.submit(app.form('native-consent',{acknowledge:'on'},{target:'dm:'+nativeId}));}

