test('a fifty-message window polls after its newest sequence even when the history cursor points to its oldest',async()=>{
 const app=client();await app.start();const messages=Array.from({length:50},(_,index)=>nativeMessage('window-'+(index+1),index+1,'Loaded '+(index+1)));nativeFixture(app,{messages});app.server.replies.set('/api/messages/conversations/'+nativeId+'/messages?limit=50',app.response({messages,changes:[],hasMore:false,cursor:1,changeCursor:9,securityMode:'standard',page:{before:1,after:50,hasMore:false}}));await app.api.openNativeConversation(nativeId);assert.equal(app.api.state.nativeCursor,50);app.server.replies.set('/api/messages/conversations/'+nativeId+'/messages?after=50&changesAfter=9&limit=100',app.response({messages:[nativeMessage('window-51',51,'Next')],changes:[],cursor:51,changeCursor:10,securityMode:'standard',page:{after:51}}));await app.api.refreshNativeMessages();assert.equal(app.api.state.nativeCursor,51);assert.equal(app.api.state.nativeMessages.length,51);assert.ok(app.calls.some(c=>c.url.includes('/messages?after=50&changesAfter=9')));assert.ok(!app.calls.some(c=>c.url.includes('/messages?after=1&')));
});

